"""Regenerates tests/fixtures/generated/tiny.jksong, the commit-safe song fixture.

    python -I tests/fixtures/generated/make_tiny.py [out.jksong]

Four seconds of generated audio (tests/conformance/synth.py: a sung-like melody with
vibrato, a backing "ooh", synthetic kick and hi-hat, bass and pad), 44.1 kHz stereo,
four 24-bit FLAC stems that sum back to the source, letter-timed lyrics
("Hello café" / "naïve world," with a precomposed é and a combining diaeresis), a
generated PNG cover, and initial settings. The "other" stem peaks above full scale so
the gain rule is exercised (gain > 1).

Deterministic: fixed seed, fixed timestamps, so regenerating with the same numpy /
libsndfile versions gives the same bytes. No third-party material: everything is
generated by formulas in this repository (GPL-3.0-or-later).
"""

from __future__ import annotations

import hashlib
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
REPO = HERE.parents[2]
sys.path.insert(0, str(REPO / "studio"))
sys.path.insert(0, str(REPO / "tests" / "conformance"))

from jukeoke_studio import jksong  # noqa: E402
from synth import png_gradient, synth  # noqa: E402

SR = 44100
FIXED_TIME = "2026-11-17T00:00:00Z"
MAX_BYTES = 600_000
# Small settings slots (16 KiB instead of the usual 256 KiB): the two slots would
# otherwise be half of this tiny file. Any multiple of 4096 is valid (SONG_FORMAT 2),
# and it keeps readers honest about not assuming 262144.
SLOT_SIZE = 16_384


def main(out: Path) -> None:
    stems, source, lyrics = synth(sr=SR, seconds=4.0, seed=7, other_peak=1.08)
    state = jksong.default_user_state()
    state["updated_utc"] = FIXED_TIME
    manifest = jksong.write_song(
        out,
        # Exact-residual mode: "other" = source - decoded(lead, backing, drums).
        stems=[jksong.StemInput(r, None if r == "other" else a) for r, a in stems.items()],
        source=source, residual_role="other",
        sample_rate=SR,
        title="Tiny generated song", artist="Jukeoke test generator", album=None,
        lyrics=lyrics, cover=png_gradient(),
        analysis={"key": {"tonic": "A", "mode": "major", "name": "A major", "confidence": 1.0}, "tempo_bpm": 120.0},
        preset="full", stems_sum_to_source=True,
        provenance={
            "app": {"name": "Jukeoke", "version": "0.1.0"},
            "studio": None,
            "source": {"filename": "generated", "sha256": hashlib.sha256(source.tobytes()).hexdigest(),
                       "container": "generated", "codec": "pcm_f32", "sample_rate": SR, "channels": 2,
                       "bits_per_sample": 32, "lossy": False},
            "models": [], "resampling": [], "created_utc": FIXED_TIME,
            "generator": "tests/fixtures/generated/make_tiny.py (tests/conformance/synth.py, seed 7)",
        },
        user_state=state,
        slot_size=SLOT_SIZE,
    )
    size = out.stat().st_size
    gains = {s["role"]: round(s["gain"], 6) for s in manifest["stems"]}
    print(f"wrote {out}: {size} bytes, gains {gains}")
    if size > MAX_BYTES:
        sys.exit(f"fixture is {size} bytes, over the {MAX_BYTES}-byte limit")


if __name__ == "__main__":
    main(Path(sys.argv[1]) if len(sys.argv) > 1 else HERE / "tiny.jksong")
